insert into public.exercises (id,name,kind,muscle,equipment,level,unit,instructions,tips) values
('squat_bw','Sentadilla con peso corporal','strength','piernas',array[]::text[],'beginner','reps',array['Pies al ancho de hombros, puntas ligeramente hacia afuera.','Baja llevando la cadera atrás y abajo, con la espalda recta.','Baja hasta donde mantengas el talón apoyado y sube empujando el suelo.']::text[],'Rodillas en línea con las puntas de los pies.'),
('goblet_squat','Sentadilla goblet','strength','piernas',array['dumbbells']::text[],'beginner','reps',array['Sostén una mancuesta contra el pecho con ambas manos.','Baja en sentadilla manteniendo el torso erguido.','Sube empujando con todo el pie.']::text[],'Codos hacia adentro, entre las rodillas al bajar.'),
('back_squat','Sentadilla con barra','strength','piernas',array['barbell']::text[],'intermediate','reps',array['Barra sobre la parte alta de la espalda, pecho arriba.','Baja controlado con la cadera atrás hasta paralelo o lo que permita tu movilidad.','Sube con fuerza sin despegar los talones.']::text[],'Empieza ligero; usa soportes de seguridad.'),
('leg_press','Prensa de piernas','strength','piernas',array['machines']::text[],'beginner','reps',array['Siéntate con la espalda apoyada y pies al ancho de hombros en la plataforma.','Baja las rodillas hacia el pecho sin que la zona lumbar se despegue.','Empuja sin bloquear las rodillas del todo.']::text[],'No dejes que la pelvis se enrolle al bajar.'),
('reverse_lunge','Zancada hacia atrás','strength','piernas',array[]::text[],'beginner','reps',array['De pie, da un paso largo hacia atrás.','Baja hasta que ambas rodillas estén cerca de 90°.','Empuja con el pie delantero para volver.']::text[],'Torso erguido; alterna las piernas.'),
('walking_lunge','Zancadas caminando','strength','piernas',array['dumbbells']::text[],'intermediate','reps',array['Mancuernas a los lados.','Da un paso largo y baja la rodilla trasera hacia el suelo.','Empuja y avanza con la otra pierna.']::text[],'Pasos lo bastante largos para que la rodilla delantera no pase mucho la punta del pie.'),
('bulgarian_split','Sentadilla búlgara','strength','piernas',array['bench']::text[],'intermediate','reps',array['Apoya el empeine de un pie en un banco detrás de ti.','Baja con la pierna delantera, torso ligeramente inclinado.','Sube empujando con el talón delantero.']::text[],'Si pierdes el equilibrio, hazla sin peso.'),
('step_up','Subida al banco','strength','piernas',array['bench']::text[],'beginner','reps',array['Coloca un pie completo sobre el banco.','Sube empujando con esa pierna sin impulsarte con la otra.','Baja controlado.']::text[],'Usa un banco que deje la rodilla a unos 90°.'),
('rdl_db','Peso muerto rumano con mancuernas','strength','femorales y glúteos',array['dumbbells']::text[],'beginner','reps',array['Mancuernas frente a los muslos, rodillas ligeramente flexionadas.','Lleva la cadera atrás deslizando las mancuernas por las piernas.','Vuelve apretando los glúteos.']::text[],'Espalda neutra todo el recorrido.'),
('deadlift_bb','Peso muerto con barra','strength','espalda baja, glúteos y femorales',array['barbell']::text[],'intermediate','reps',array['Barra sobre la mitad del pie, agarre al ancho de hombros.','Pecho arriba, espalda neutra, empuja el suelo.','Termina de pie con glúteos apretados; baja controlando.']::text[],'Aprende la técnica con poco peso.'),
('hip_thrust','Puente de glúteos con banco (hip thrust)','strength','glúteos',array['bench']::text[],'beginner','reps',array['Espalda alta apoyada en el banco, pies firmes en el suelo.','Empuja la cadera hacia arriba hasta alinear rodillas, cadera y hombros.','Aprieta los glúteos arriba y baja controlado.']::text[],'Mentón recogido; no arquees la zona lumbar.'),
('hip_thrust_bb','Hip thrust con barra','strength','glúteos',array['bench','barbell']::text[],'intermediate','reps',array['Apoya la espalda en el banco con la barra sobre la cadera (usa protector).','Empuja la cadera hasta alinear el torso con los muslos.','Pausa 1 segundo arriba y baja.']::text[],'Aumenta el peso gradualmente.'),
('glute_bridge','Puente de glúteos','strength','glúteos',array[]::text[],'beginner','reps',array['Tumbada/o boca arriba con rodillas flexionadas.','Eleva la cadera apretando los glúteos.','Baja sin apoyar del todo y repite.']::text[],'Empuja con los talones.'),
('glute_kickback_band','Patada de glúteo con banda','strength','glúteos',array['bands']::text[],'beginner','reps',array['En cuadrupedia con la banda en los pies.','Extiende una pierna hacia atrás apretando el glúteo.','Vuelve sin descansar y completa las repeticiones.']::text[],'No arquees la espalda.'),
('clamshell_band','Almeja con banda','strength','glúteo medio',array['bands']::text[],'beginner','reps',array['De lado con rodillas flexionadas y banda sobre las rodillas.','Abre la rodilla de arriba sin mover la pelvis.','Baja controlado.']::text[],'Pies juntos.'),
('leg_curl','Curl femoral en máquina','strength','femorales',array['machines']::text[],'beginner','reps',array['Ajusta la máquina y apoya las piernas.','Flexiona llevando los talones hacia los glúteos.','Vuelve lento.']::text[],'Evita levantar la cadera.'),
('leg_extension','Extensión de cuádriceps','strength','cuádriceps',array['machines']::text[],'beginner','reps',array['Ajusta el respaldo y el rodillo.','Extiende las piernas sin bloquear de golpe.','Baja con control.']::text[],'Peso moderado si tienes molestias de rodilla.'),
('calf_raise','Elevación de talones','strength','gemelos',array[]::text[],'beginner','reps',array['De pie, apoya la punta de los pies.','Sube de puntillas todo lo que puedas.','Baja lento.']::text[],'Agárrate a una pared para equilibrio.'),
('pushup','Flexiones','strength','pecho, hombros y tríceps',array[]::text[],'intermediate','reps',array['Manos algo más anchas que los hombros, cuerpo en línea recta.','Baja el pecho hacia el suelo con codos a ~45°.','Empuja hasta extender los brazos.']::text[],'Si no puedes, usa flexiones de rodillas.'),
('knee_pushup','Flexiones de rodillas','strength','pecho, hombros y tríceps',array[]::text[],'beginner','reps',array['Rodillas apoyadas, cuerpo recto de rodillas a cabeza.','Baja el pecho al suelo con control.','Empuja hasta arriba.']::text[],'Progresa a flexiones completas.'),
('db_bench','Press de pecho con mancuernas','strength','pecho',array['dumbbells','bench']::text[],'beginner','reps',array['Tumbada/o en el banco con mancuernas a la altura del pecho.','Empuja hacia arriba hasta extender los brazos.','Baja lento hasta sentir estiramiento en el pecho.']::text[],'Omóplatos juntos y apoyados.'),
('bb_bench','Press de banca con barra','strength','pecho',array['barbell','bench']::text[],'intermediate','reps',array['Agarre algo más ancho que los hombros, pies firmes.','Baja la barra al pecho controlada.','Empuja hasta extender.']::text[],'Pide ayuda o usa soportes con cargas altas.'),
('db_incline','Press inclinado con mancuernas','strength','pecho superior',array['dumbbells','bench']::text[],'intermediate','reps',array['Banco inclinado ~30°.','Empuja las mancuernas hacia arriba.','Baja controlado.']::text[],'No uses una inclinación excesiva.'),
('db_shoulder_press','Press de hombros con mancuernas','strength','hombros',array['dumbbells']::text[],'beginner','reps',array['Sentada/o o de pie, mancuernas a la altura de los hombros.','Empuja hacia arriba sin arquear la espalda.','Baja controlado.']::text[],'Abdomen firme.'),
('lateral_raise','Elevaciones laterales','strength','hombros',array['dumbbells']::text[],'beginner','reps',array['Mancuernas a los lados, codos ligeramente flexionados.','Sube los brazos hasta la altura de los hombros.','Baja lento.']::text[],'Peso ligero, sin balanceo.'),
('db_row','Remo con mancuerna','strength','espalda',array['dumbbells','bench']::text[],'beginner','reps',array['Apoya una mano y rodilla en el banco, espalda plana.','Tira de la mancuerna hacia la cadera.','Baja estirando el brazo.']::text[],'Lleva el codo hacia atrás, no el hombro.'),
('band_row','Remo con banda','strength','espalda',array['bands']::text[],'beginner','reps',array['Sentada/o con la banda en los pies.','Tira de los extremos hacia el abdomen juntando omóplatos.','Vuelve lento.']::text[],'Espalda recta.'),
('lat_pulldown','Jalón al pecho','strength','espalda',array['machines']::text[],'beginner','reps',array['Agarre ancho, pecho arriba.','Tira de la barra hacia la clavícula.','Sube controlado.']::text[],'Evita balancear el torso.'),
('seated_row','Remo en máquina','strength','espalda',array['machines']::text[],'beginner','reps',array['Pecho apoyado o espalda recta.','Tira de los agarres hacia el torso.','Vuelve lento.']::text[],'Hombros abajo y atrás.'),
('pullup','Dominadas','strength','espalda y bíceps',array['pullup']::text[],'advanced','reps',array['Agarre algo más ancho que los hombros.','Sube hasta pasar la barbilla de la barra.','Baja controlado.']::text[],'Si no puedes, usa jalón al pecho.'),
('face_pull_band','Face pull con banda','strength','hombro posterior',array['bands']::text[],'beginner','reps',array['Banda a la altura del rostro.','Tira hacia la cara abriendo los codos.','Vuelve lento.']::text[],'Mejora la postura.'),
('db_curl','Curl de bíceps con mancuernas','strength','bíceps',array['dumbbells']::text[],'beginner','reps',array['Codos pegados al cuerpo.','Flexiona llevando las mancuernas a los hombros.','Baja lento.']::text[],'Sin balancear el torso.'),
('hammer_curl','Curl martillo','strength','bíceps y antebrazo',array['dumbbells']::text[],'beginner','reps',array['Palmas enfrentadas.','Flexiona manteniendo los codos fijos.','Baja controlado.']::text[],'Muñecas neutras.'),
('bench_dip','Fondos en banco','strength','tríceps',array['bench']::text[],'beginner','reps',array['Manos en el banco detrás de ti, piernas estiradas o dobladas.','Baja flexionando los codos hacia atrás.','Sube extendiendo.']::text[],'Si molesta el hombro, usa extensión de tríceps.'),
('db_triceps_ext','Extensión de tríceps con mancuerna','strength','tríceps',array['dumbbells']::text[],'beginner','reps',array['Sostén una mancuerna con ambas manos sobre la cabeza.','Flexiona los codos bajando detrás de la cabeza.','Extiende sin abrir los codos.']::text[],'Codos apuntando al frente.'),
('kb_swing','Swing con pesa rusa','strength','glúteos y espalda',array['kettlebell']::text[],'intermediate','reps',array['Pies al ancho de hombros, pesa entre las piernas.','Empuja la cadera adelante con fuerza para elevar la pesa.','Deja que vuelva y repite con bisagra de cadera.']::text[],'El movimiento viene de la cadera, no de los brazos.'),
('plank','Plancha','core','abdomen',array[]::text[],'beginner','seconds',array['Antebrazos apoyados, cuerpo en línea recta.','Aprieta abdomen y glúteos.','Mantén la posición sin hundir la cadera.']::text[],'Respira de forma continua.'),
('side_plank','Plancha lateral','core','oblicuos',array[]::text[],'intermediate','seconds',array['Apoya un antebrazo, cuerpo en línea.','Eleva la cadera y mantén.','Cambia de lado.']::text[],'Si es difícil, apoya la rodilla.'),
('dead_bug','Bicho muerto','core','abdomen',array[]::text[],'beginner','reps',array['Boca arriba, brazos al techo y rodillas a 90°.','Extiende brazo y pierna contrarios sin despegar la zona lumbar.','Alterna lados.']::text[],'Lento y controlado.'),
('bird_dog','Perro-pájaro','core','core y espalda baja',array[]::text[],'beginner','reps',array['En cuadrupedia.','Extiende brazo y pierna contrarios.','Vuelve y alterna.']::text[],'Pelvis estable.'),
('mountain_climber','Escaladores','cardio','core y cardio',array[]::text[],'intermediate','seconds',array['En posición de plancha alta.','Lleva las rodillas al pecho alternando a ritmo constante.','Mantén la cadera baja.']::text[],'Reduce el ritmo si pierdes la forma.'),
('brisk_walk','Caminata rápida','cardio','cardio',array[]::text[],'beginner','minutes',array['Camina a un ritmo en el que puedas hablar con esfuerzo.','Mantén la postura erguida.','Termina bajando el ritmo.']::text[],'Ideal para días de recuperación activa.'),
('easy_jog','Trote suave','cardio','cardio',array[]::text[],'intermediate','minutes',array['Ritmo cómodo, respiración controlada.','Apoya con suavidad.','Termina caminando unos minutos.']::text[],'Aumenta el tiempo de forma gradual.'),
('stationary_bike','Bicicleta fija','cardio','cardio',array['machines']::text[],'beginner','minutes',array['Ajusta el asiento a la altura de la cadera.','Pedalea a ritmo constante con resistencia moderada.','Termina con 2 min suaves.']::text[],'Ideal si cuidas las rodillas o articulaciones.'),
('cat_cow','Gato-vaca','mobility','columna',array[]::text[],'beginner','seconds',array['En cuadrupedia, arquea y redondea la espalda alternando.','Sigue el ritmo de tu respiración.']::text[],'Movimientos suaves.'),
('worlds_greatest','Estiramiento dinámico de cadera y torácica','mobility','cadera y torácica',array[]::text[],'beginner','seconds',array['Zancada profunda con las manos en el suelo.','Gira el torso y eleva un brazo al techo.','Alterna lados.']::text[],'Sin dolor.'),
('hip_circles','Círculos de cadera','mobility','cadera',array[]::text[],'beginner','seconds',array['De pie, apoya una mano y dibuja círculos amplios con la rodilla elevada.','Cambia de dirección y de pierna.']::text[],'Mantén la pelvis estable.'),
('arm_circles','Círculos de brazos','mobility','hombros',array[]::text[],'beginner','seconds',array['Brazos extendidos a los lados.','Círculos pequeños que van creciendo.','Cambia de dirección.']::text[],'Hombros relajados.'),
('hip_flexor_stretch','Estiramiento de flexor de cadera','mobility','cadera',array[]::text[],'beginner','seconds',array['Rodilla en el suelo en zancada.','Lleva la cadera adelante hasta sentir estiramiento.','Mantén y cambia de lado.']::text[],'Aprieta el glúteo de la pierna de atrás.'),
('hamstring_stretch','Estiramiento de femorales','mobility','femorales',array[]::text[],'beginner','seconds',array['Sentada/o con una pierna estirada.','Inclina el torso hacia el pie con la espalda larga.','Mantén sin rebotar.']::text[],'Estira hasta una tensión suave.'),
('childs_pose','Postura del niño','mobility','espalda y cadera',array[]::text[],'beginner','seconds',array['De rodillas, siéntate sobre los talones.','Estira los brazos al frente y relaja.','Respira profundo.']::text[],'Ideal para cerrar la sesión.'),
('thoracic_rotation','Rotación torácica','mobility','columna torácica',array[]::text[],'beginner','seconds',array['En cuadrupedia con una mano detrás de la cabeza.','Gira abriendo el codo al techo.','Alterna lados.']::text[],'Mueve solo la parte alta de la espalda.')
insert into public.supplement_knowledge (slug,aliases,summary,cautions,watch_terms,always_consult) values
('creatine',array['creatina','creatine']::text[],'Se usa para mejorar el rendimiento en esfuerzos cortos e intensos. Es de los suplementos más estudiados.','Puede retener agua. Si tienes problemas de riñón o tomas medicamentos que lo afecten, consulta antes con un profesional.',array['rinon','riñón','renal','kidney','diuretic','diurético']::text[],true),
('whey',array['proteina','proteína','whey','protein']::text[],'Facilita llegar a tu objetivo de proteínas diarias; no es necesaria si ya lo consigues con comida.','Revisa alergia a la leche o lactosa. Con enfermedad renal o hepática, consulta antes.',array['lactosa','leche','alergia','renal','higado','hígado']::text[],false),
('vitamin_d',array['vitamina d','vitamin d','d3']::text[],'Participa en la salud ósea e inmunitaria. La necesidad real depende de la exposición solar y análisis.','Dosis altas sostenidas pueden ser perjudiciales. Lo ideal es dosificarla según análisis y criterio médico.',array['calcio','hipercalcemia','tiazida','renal']::text[],true),
('magnesium',array['magnesio','magnesium']::text[],'Interviene en la función muscular y nerviosa.','Puede causar molestias digestivas y afectar la absorción de algunos medicamentos (antibióticos, levotiroxina). Con enfermedad renal, consulta antes.',array['antibiotico','antibiótico','levotiroxina','renal','bisfosfonato']::text[],false),
('omega3',array['omega 3','omega-3','aceite de pescado','fish oil']::text[],'Ácidos grasos con efecto en salud cardiovascular.','Puede potenciar anticoagulantes y aumentar el riesgo de sangrado.',array['anticoagul','warfarina','aspirina','sangrado','clopidogrel']::text[],false),
('caffeine',array['cafeina','cafeína','caffeine','preentreno','pre-entreno','pre workout']::text[],'Estimulante que puede mejorar el rendimiento y la alerta.','Puede empeorar el sueño, la ansiedad y la presión arterial. Evítala cerca de dormir; cuidado en embarazo y con problemas cardíacos.',array['ansiedad','hipertension','hipertensión','presion','presión','arritmia','embarazo','insomnio','corazon','corazón']::text[],false),
('iron',array['hierro','iron']::text[],'Se usa ante deficiencia de hierro.','Solo debe tomarse con deficiencia confirmada por análisis: el exceso es peligroso.',array['hemocromatosis']::text[],true),
('zinc',array['zinc']::text[],'Participa en la función inmunitaria.','Dosis altas sostenidas pueden provocar deficiencia de cobre y molestias digestivas.',array['antibiotico','antibiótico','cobre']::text[],false),
('vitamin_c',array['vitamina c','vitamin c']::text[],'Antioxidante; la mayoría de personas la cubre con frutas y verduras.','Dosis altas pueden causar molestias digestivas y cálculos renales en personas predispuestas.',array['calculos','cálculos','renal']::text[],false),
('multivitamin',array['multivitaminico','multivitamínico','multivitamin','vitaminas']::text[],'Puede cubrir carencias puntuales; no sustituye una dieta variada.','Revisa que no dupliques nutrientes con otros suplementos.',array[]::text[],false),
('calcium',array['calcio','calcium']::text[],'Importante para huesos; primero conviene cubrirlo con alimentos.','Puede interferir con algunos medicamentos (levotiroxina, antibióticos) y favorecer cálculos renales.',array['levotiroxina','antibiotico','antibiótico','calculos','cálculos','renal']::text[],false),
('b12',array['b12','vitamina b12','cobalamina']::text[],'Relevante en dietas veganas o con problemas de absorción.','Consulta si tomas metformina u otros medicamentos que afecten la absorción.',array['metformina','anemia']::text[],false)
